#include <iostream>
using namespace std;

int main() {
    double nota1, nota2, media;       // var ... : real
    cout << "Digite a nota 1: ";      // escreva
    cin >> nota1;                     // leia
    cout << "Digite a nota 2: ";
    cin >> nota2;
    media = (nota1 + nota2) / 2;      // media <- ...
    if (media >= 6) {                 // se ... entao
        cout << "Aprovado! Média: " << media << endl;
    } else {                          // senao
        cout << "Reprovado. Média: " << media << endl;
    }                                 // fimse
    return 0;
}
